import zipfile, re, json, sys
import xml.etree.ElementTree as ET

P = r"E:\TTQS\_github_sync_0064\docs\ttqs-quality-20261016\quality-review\0085_R01\candidate\0085_R06.docx"
W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"

z = zipfile.ZipFile(P)
root = ET.fromstring(z.read("word/document.xml"))
body = root.find(W+"body")

def ptext(p):
    parts=[]
    for node in p.iter():
        tag=node.tag
        if tag==W+"t":
            parts.append(node.text or "")
        elif tag==W+"tab":
            parts.append("\t")
        elif tag in (W+"br", W+"cr"):
            parts.append("\n")
    return "".join(parts)

def celltext(tc):
    ps=[]
    for p in tc.findall(W+"p"):
        ps.append(ptext(p))
    return "\n".join(ps)

blocks=[]
for child in list(body):
    if child.tag==W+"p":
        blocks.append(("P", ptext(child)))
    elif child.tag==W+"tbl":
        rows=[]
        for tr in child.findall(W+"tr"):
            cells=[]
            for tc in tr.findall(W+"tc"):
                cells.append(celltext(tc))
            rows.append(cells)
        blocks.append(("T", rows))

tables=[(i,b[1]) for i,b in enumerate(blocks) if b[0]=="T"]
print("BLOCKS",len(blocks),"TABLES",len(tables),"PARAS",sum(1 for b in blocks if b[0]=="P"))
print("SECTPR", len(root.findall('.//'+W+'sectPr')))

# nearest preceding paragraph that looks like a heading
def heading_before(idx):
    for j in range(idx-1,-1,-1):
        if blocks[j][0]=="P":
            t=blocks[j][1].strip()
            if re.match(r'^(§|附錄|\d+\.\d|1[0-9]\.)', t) or t.startswith("附錄"):
                return t[:90]
    return ""

for n,(idx,rows) in enumerate(tables,1):
    ncols=max((len(r) for r in rows), default=0)
    hdr=" | ".join(rows[0])[:150] if rows else ""
    print(f"T{n:02d} block={idx} dims={len(rows)}x{ncols} near={heading_before(idx)!r} HDR={hdr!r}")

