import json, re, zipfile, collections
import xml.etree.ElementTree as ET
B=json.load(open(r"C:\Users\J\AppData\Local\Temp\opencode\r06_blocks.json",encoding="utf-8"))
P=r"E:\TTQS\_github_sync_0064\docs\ttqs-quality-20261016\quality-review\0085_R01\candidate\0085_R06.docx"
R=[]
def w(s=""): R.append(str(s))

paras=[(i,b["t"]) for i,b in enumerate(B) if b["k"]=="P"]
tables=[(i,b["rows"]) for i,b in enumerate(B) if b["k"]=="T"]
def fulltext(): 
    parts=[t for _,t in paras]
    for _,rows in tables:
        for r in rows: parts.extend(r)
    return "\n".join(parts)
FT=fulltext()

def show_para(pat, limit=50):
    n=0
    for i,t in paras:
        if re.search(pat,t):
            w(f"P{i}: {t}")
            n+=1
            if n>=limit: break

w("===== CHAR COUNTS D01-D08 TD-3 =====")
t132={i:rows for i,rows in tables}
rows=[r for i,rows in tables if i==159][0]
for r in rows[1:]:
    s=r[3]
    cjk=len(re.findall(r'[\u3400-\u9fff]',s))
    nopunct=len(re.sub(r'[，。；：、「」？！（）／—…]','',s))
    w(f"{r[0]}: len={len(s)} cjk={cjk} nopunct={nopunct} text={s!r}")

w("\n===== ALL PARAGRAPHS 0-70 =====")
for i,t in paras:
    if i<=70: w(f"P{i}: {t}")

w("\n===== PARAGRAPHS 145-205 =====")
for i,t in paras:
    if 145<=i<=205: w(f"P{i}: {t}")

w("\n===== PARAGRAPHS 235-294 =====")
for i,t in paras:
    if i>=235: w(f"P{i}: {t}")

w("\n===== FORBIDDEN / SENSITIVE TERM HITS =====")
terms=["READY","ACCEPTED","REVIEWED","PASS","核准","核定","批准","已採納","本會規定","正式驗收","委員會","理事長","董事會","頒","受領","已達","成效提升","證明有效","導致","顯著改善","見附件","全體一致","無異議","圓滿結案","全部合格","已正式"]
for term in terms:
    hits=[]
    for i,t in paras:
        if term in t: hits.append(f"P{i}:{t}")
    for i,rows in tables:
        for ri,r in enumerate(rows):
            for ci,c in enumerate(r):
                if term in c: hits.append(f"Tbl@{i}[{ri},{ci}]:{c}")
    w(f"\n-- {term} ({len(hits)})")
    for h in hits[:25]: w("   "+h)

w("\n===== SYN-ACT-01 occurrences =====")
for i,t in paras:
    if "SYN-ACT-01" in t: w(f"P{i}: {t}")
for i,rows in tables:
    for ri,r in enumerate(rows):
        for ci,c in enumerate(r):
            if "SYN-ACT-01" in c: w(f"Tbl@{i}[{ri},{ci}]: {c}")

w("\n===== SERIES CODE occurrences count =====")
w("SYN-KM-SERIES-2026-C count="+str(FT.count("SYN-KM-SERIES-2026-C")))
for other in ["SYN-0083-B01","LRN-B01","SYN-0073","BTR-","AID-01","83.3"]:
    w(f"{other} count={FT.count(other)}")

w("\n===== APPENDIX E locator/field consistency =====")
app=[rows for i,rows in tables if i==293][0]
bad=[]; seccount=collections.Counter()
for r in app[1:]:
    loc, fid = r[1], r[2]
    m=re.match(r"§(13\.(?:[0-9]+)(?:\.[0-9]+)?)/(.*)",loc)
    if not m:
        bad.append(("badloc",r)); continue
    sec=m.group(1); rest=m.group(2)
    # field check: fid appears in loc, or loc is KI-nn/KI-xx
    if fid not in loc:
        bad.append(("field_not_in_loc",r))
    # group count normalized
    if sec.startswith("13.10"): g="13.10"
    elif sec.startswith("13.11"): g="13.11"
    else: g=sec
    seccount[g]+=1
